1166	function pidAlive(pid: number): boolean {
1167	  try {
1168	    process.kill(pid, 0);
1169	    return true;
1170	  } catch (e) {
1171	    return (e as NodeJS.ErrnoException).code === 'EPERM'; // 存在但无权发信号：视为存活
1172	  }
