1181	 * 返回 null 表示锁被存活进程持有（或刚好被释放/替换，下一轮重试即可）。
1182	 * 内容尚不可解析的锁视为“刚创建、内容未写完”，短暂宽限内不抢占，超过宽限按
1183	 * 异常遗留处理。
1184	 */
1185	function staleLockContent(path: string): string | null {
1186	  let content: string;
1187	  try {
1188	    content = readFileSync(path, 'utf8');
1189	  } catch {
