1227	  const deadline = Date.now() + limit;
1228	  const path = join(dataDir, LOCK_FILENAME);
1229	  const content = `${process.pid} ${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}\n`;
1230	  try {
1231	    mkdirSync(dataDir, { recursive: true }); // 首次使用：先建目录再竞争锁，并发创建同样安全
1232	  } catch (e) {
1233	    throw new DataError(`无法创建数据目录 ${dataDir}：${(e as Error).message}`);
1234	  }
1235	  for (;;) {
1236	    try {
1237	      writeFileSync(path, content, { flag: 'wx' }); // 原子创建：已存在即失败
1238	      cleanStaleTmpFiles(dataDir);
1239	      let released = false;
1240	      return {
1241	        release(): void {
1242	          if (released) return;
1243	          released = true;
1244	          try {
1245	            // 仅当锁仍由本请求持有时删除，绝不错删其他写进程的锁
1246	            if (readFileSync(path, 'utf8') === content) unlinkSync(path);
