1261	      try {
1262	        if (readFileSync(path, 'utf8') === stale) {
1263	          const trash = `${path}.stale.${process.pid}`;
1264	          try {
1265	            renameSync(path, trash);
1266	            unlinkSync(trash);
1267	          } catch {
