1269	          }
1270	        }
1271	      } catch {
1272	        /* 锁已被释放或替换：直接重试 */
1273	      }
1274	      continue;
1275	    }
1276	    if (Date.now() >= deadline) {
1277	      throw new DataError(
1278	        `数据目录正忙：等待写入机会超过 ${limit} 毫秒仍未获得（另一进程正在写入 ${dataDir}）；` +
1279	          `本次请求未做任何改动，请稍后重试`,
1280	      );
