1286	// ---------- 参数解析 ----------
1287	
1288	interface ParsedArgs {
1289	  positionals: string[];
1290	  flags: Record<string, string>;
1291	  multi: Record<string, string[]>;
1292	}
1293	
1294	function parseArgs(
1295	  tokens: string[],
1296	  singles: string[],
1297	  multis: string[] = [],
1298	): ParsedArgs {
1299	  const out: ParsedArgs = { positionals: [], flags: {}, multi: {} };
1300	  const singleSet = new Set(singles);
1301	  const multiSet = new Set(multis);
1302	
1303	  for (let i = 0; i < tokens.length; i++) {
1304	    const tok = tokens[i];
1305	    if (tok.startsWith('--')) {
1306	      let key = tok;
1307	      let value: string | undefined;
1308	      const eq = tok.indexOf('=');
1309	      if (eq >= 0) {
1310	        key = tok.slice(0, eq);
1311	        value = tok.slice(eq + 1);
1312	      }
1313	      if (!singleSet.has(key) && !multiSet.has(key)) throw new UsageError(`未知参数：${tok}`);
1314	      if (value === undefined) {
1315	        if (i + 1 >= tokens.length) throw new UsageError(`参数 ${key} 缺少取值`);
1316	        value = tokens[++i];
1317	      }
1318	      if (multiSet.has(key)) (out.multi[key] ??= []).push(value);
1319	      else if (out.flags[key] !== undefined) throw new UsageError(`参数 ${key} 重复指定`);
1320	      else out.flags[key] = value;
1321	    } else {
1322	      out.positionals.push(tok);
1323	    }
1324	  }
1325	  return out;
1326	}
