1328	function parseItem(raw: string, merged: Map<string, number>): void {
1329	  const idx = raw.indexOf(':');
1330	  if (idx <= 0) throw new BizError(`明细格式应为 “商品编号:数量”：${raw}`);
1331	  const pid = trimOrThrow('商品编号', raw.slice(0, idx));
1332	  const qtyRaw = raw.slice(idx + 1).trim();
1333	  if (!/^\d+$/.test(qtyRaw)) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
1334	  const qty = Number(qtyRaw);
1335	  if (!Number.isSafeInteger(qty) || qty <= 0) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
1336	  const sum = (merged.get(pid) ?? 0) + qty; // 同单同商品先合并
1337	  if (!Number.isSafeInteger(sum)) throw new BizError(`商品 ${pid} 累计数量超出安全整数范围`);
1338	  merged.set(pid, sum);
1339	}

