1567	/**
1568	 * 解析整批导入文件。文件级结构错误（非合法 JSON、根不是数组、空列表）属于文件
1569	 * 格式错误（退出 2）；逐项格式不合法属于业务拒绝（退出 1），指出位置与原因。
1570	 */
1571	function parseImportFile(raw: string): ImportRequest[] {
1572	  let data: unknown;
1573	  try {
1574	    data = JSON.parse(raw);
1575	  } catch (e) {
1576	    throw new UsageError(`导入文件不是合法 JSON：${(e as Error).message}`);
1577	  }
1578	  if (!Array.isArray(data)) throw new UsageError('导入文件格式错误：根节点必须是单据对象组成的有序数组');
1579	  if (data.length === 0) throw new UsageError('导入文件格式错误：单据列表至少包含一项');
1580	
1581	  const out: ImportRequest[] = [];
1582	  // 顶层位置一律标注 1 起序号，便于纠正
1583	  const at = (i: number, msg: string): BizError => new BizError(`第 ${i + 1} 项：${msg}`);
1584	
1585	  const requireString = (obj: Record<string, unknown>, key: string, label: string, i: number): string => {
1586	    const v = obj[key];
1587	    if (v === undefined) throw at(i, `缺少${label}字段 "${key}"`);
1588	    if (typeof v !== 'string') throw at(i, `${label}字段 "${key}" 必须是字符串`);
1589	    const s = v.trim();
1590	    if (s === '') throw at(i, `${label}去除首尾空白后不能为空`);
1591	    return s;
1592	  };
1593	
1594	  const checkUnknown = (obj: Record<string, unknown>, allowed: readonly string[], i: number): void => {
1595	    for (const k of Object.keys(obj)) {
1596	      if (!allowed.includes(k)) throw at(i, `含不支持的字段 "${k}"（允许字段：${allowed.join('、')}）`);
1597	    }
1598	  };
1599	
1600	  const parseQtyItems = (obj: Record<string, unknown>, i: number): Map<string, number> => {
1601	    const v = obj.items;
1602	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
1603	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
1604	    if (v.length === 0) throw at(i, '商品明细至少一项');
1605	    const merged = new Map<string, number>();
1606	    v.forEach((entry, j) => {
1607	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
1608	      const e = entry as Record<string, unknown>;
1609	      checkUnknown(e, ['product', 'qty'], i);
1610	      const pid = e.product;
1611	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
1612	      const p = pid.trim();
1613	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
1614	      if (!isPosSafeInt(e.qty)) throw at(i, `商品 ${p} 的数量必须为正安全整数`);
1615	      const sum = (merged.get(p) ?? 0) + (e.qty as number); // 同单同商品先合并
1616	      if (!Number.isSafeInteger(sum)) throw at(i, `商品 ${p} 累计数量超出安全整数范围`);
1617	      merged.set(p, sum);
1618	    });
1619	    return merged;
1620	  };
1621	
1622	  const parseCountItems = (obj: Record<string, unknown>, i: number): Map<string, CountItem> => {
1623	    const v = obj.items;
1624	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
1625	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
1626	    if (v.length === 0) throw at(i, '商品明细至少一项');
1627	    const items = new Map<string, CountItem>();
1628	    v.forEach((entry, j) => {
1629	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
1630	      const e = entry as Record<string, unknown>;
1631	      checkUnknown(e, ['product', 'expected', 'actual'], i);
1632	      const pid = e.product;
1633	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
1634	      const p = pid.trim();
1635	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
1636	      if (!isNonNegSafeInt(e.expected)) throw at(i, `商品 ${p} 的预期账面量必须为非负安全整数`);
1637	      if (!isNonNegSafeInt(e.actual)) throw at(i, `商品 ${p} 的实盘量必须为非负安全整数`);
1638	      if (items.has(p)) throw at(i, `盘点明细中商品 ${p} 重复出现，拒绝提交`); // 盘点不合并
1639	      items.set(p, { expected: e.expected, actual: e.actual });
1640	    });
1641	    return items;
1642	  };
1643	
1644	  data.forEach((rawItem, i) => {
1645	    if (!isPlainObject(rawItem)) throw at(i, '不是单据对象');
1646	    const item = rawItem as Record<string, unknown>;
1647	    if (item.type === undefined) throw at(i, '缺少业务类型字段 "type"');
1648	    if (typeof item.type !== 'string') throw at(i, '业务类型字段 "type" 必须是字符串');
1649	
1650	    switch (item.type) {
1651	      case 'in':
1652	      case 'out': {
1653	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
1654	        const docId = requireString(item, 'id', '单据编号', i);
