1665	        out.push({ kind: 'doc', req: { type: 'transfer', docId, from, to, items: parseQtyItems(item, i) } });
1666	        break;
1667	      }
1668	      case 'count': {
1669	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
1670	        const docId = requireString(item, 'id', '单据编号', i);
1671	        const wh = requireString(item, 'wh', '仓库标识', i);
1672	        out.push({ kind: 'count', req: { docId, wh, items: parseCountItems(item, i) } });
1673	        break;
1674	      }
1675	      case 'reverse': {
1676	        checkUnknown(item, ['type', 'id', 'orig'], i);
1677	        const docId = requireString(item, 'id', '冲销单编号', i);
1678	        const orig = requireString(item, 'orig', '原单编号', i);
1679	        out.push({ kind: 'reverse', docId, orig });
1680	        break;
1681	      }
1682	      case 'po': {
1683	        checkUnknown(item, ['type', 'id', 'supplier', 'wh', 'items'], i);
1684	        const poId = requireString(item, 'id', '采购编号', i);
1685	        const supplier = requireString(item, 'supplier', '供应商名称', i);
1686	        const wh = requireString(item, 'wh', '收货仓标识', i);
1687	        out.push({ kind: 'po', req: { poId, supplier, wh, items: parseQtyItems(item, i) } });
1688	        break;
1689	      }
1690	      case 'arrival': {
1691	        checkUnknown(item, ['type', 'id', 'po', 'items'], i);
1692	        const arrId = requireString(item, 'id', '到货单编号', i);
1693	        const poId = requireString(item, 'po', '采购编号', i);
1694	        out.push({ kind: 'arrival', req: { arrId, poId, items: parseQtyItems(item, i) } });
1695	        break;
1696	      }
