const LOCK_PREFIX = `.${DATA_FILENAME}.lock.`;
const LOCK_GLOB = `.${DATA_FILENAME}.lock`; // 观察目录时匹配此前缀（含旧式单文件）
const LEGACY_LOCK_FILENAME = `.${DATA_FILENAME}.lock`;
const TMP_PREFIX = `.${DATA_FILENAME}.`;
const LOCK_WAIT_DEFAULT_MS = 10_000;
const LOCK_POLL_MS = 50;

interface WriteLock {
  release(): void;
}

/** 解析并校验等待上限：仅接受非负安全整数；0 = 仅立即尝试；非法配置抛用法错误（退出 2）。 */
function lockWaitLimitMs(): number {
  const raw = process.env.STOCKROOM_LOCK_WAIT_MS;
  if (raw === undefined) return LOCK_WAIT_DEFAULT_MS;
  if (!/^\d+$/.test(raw.trim()))
    throw new UsageError(
      `环境变量 STOCKROOM_LOCK_WAIT_MS 必须是非负整数毫秒（0 表示仅尝试立即取得），实际为：${raw}`,
    );
  const n = Number(raw.trim());
  if (!Number.isSafeInteger(n))
    throw new UsageError(
      `环境变量 STOCKROOM_LOCK_WAIT_MS 超出安全整数范围，拒绝启动（不能转换为无限等待）：${raw}`,
    );
  return n;
}

function pidAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch (e) {
    return (e as NodeJS.ErrnoException).code === 'EPERM'; // 存在但无权发信号：视为存活
  }
}

function sleepSync(ms: number): void {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

/** 把（可能含符号链接的）数据目录归一为真实路径，使同一目录的不同写法共用一把锁。 */
function resolveDataDir(dataDir: string): string {
  try {
    return realpathSync.native(dataDir);
  } catch {
    // 目录尚不存在：先归一父目录（可能本身是符号链接），再拼上待创建的末级
    const abs = resolve(dataDir);
    const slash = Math.max(abs.lastIndexOf('/'), 0);
    const parent = abs.slice(0, slash) || '/';
    const base = abs.slice(slash + 1);
    try {
      return join(realpathSync.native(parent), base);
    } catch {
      return abs;
    }
  }
}

/**
 * 列出当前锁文件名（不含目录前缀）。包括两种形态：
 *   - 旧式单文件 .stockroom.json.lock（历史遗留）
 *   - 新式 .stockroom.json.lock.<pid>.<nonce>
 * 其余临时文件、数据文件一律忽略。
 */
function listLockFiles(dir: string): string[] {
  let names: string[];
  try {
    names = readdirSync(dir);
  } catch {
    return [];
  }
  return names.filter((n) => n === LEGACY_LOCK_FILENAME || n.startsWith(LOCK_PREFIX));
}

/**
 * 判断一个锁文件是否属于已退出的写进程（可安全回收）。
 * 新式锁的 pid 取自文件名：持有者仍存活时，无论内容为空、写了一半还是已写
 * 完整，都一律视为占用中——文件年龄与内容完整度从不作为抢占依据。
 * 旧式锁（升级前遗留）回退读取首行 pid；无法解析内容时不按年龄抢占，避免
 * 误伤“创建后尚未写完持有者信息”的存活进程。
 * 返回 true 表示可回收，false 表示存活占用或无法判定（下一轮重试）。
 */
function lockIsStale(dir: string, name: string): boolean {
  if (name.startsWith(LOCK_PREFIX)) {
    const rest = name.slice(LOCK_PREFIX.length);
    const dot = rest.indexOf('.');
    const pidPart = dot < 0 ? rest : rest.slice(0, dot);
    if (!/^\d+$/.test(pidPart)) return false; // 文件名异常：保守起见不回收
