// ---------- 多进程写入协调 ----------
//
// 同一数据目录的写请求用目录内的锁文件串行化：取得写入机会后才读取最新已提交
// 状态，业务校验、去重与原子保存（临时文件 + rename）都在持有锁期间完成，因此
// 并发请求的最终结果等价于某个完整串行执行顺序，流水序号与该顺序一致。锁文件
// 位于数据目录内部，相对、绝对及符号链接路径经 realpath 归一后指向同一目录时
// 共用同一把锁；不同目录各有自己的锁，互不阻塞。只读查询不创建也不检查锁文件。
//
// 锁协议（文件名即占用归属，内容仅为诊断信息）：
//   锁文件名形如 .stockroom.json.lock.<pid>.<nonce>，由持有者以 O_EXCL 原子创建。
//   - 存活进程的锁永远不会被接管：即使持有者在创建文件之后、写完持有者信息之前
//     暂停很久，锁文件名仍记录着存活 pid，文件年龄与内容是否完整都不作为抢占理由。
//   - 持有者进程退出后，锁文件名中的 pid 不再存在；此时锁成为遗留物，任何等待者
//     都可回收。多个等待者同时发现遗留占用时只能串行：回收者先以 rename 把“该
//     死 pid 的具体文件”改名到唯一回收名，再原子创建自己的锁；若他人已先得手
//     （旧名消失或新锁已存在）则本轮放弃、下一轮重新观察，因此绝不会移走另一个
//     请求刚刚取得的新锁，也不会删除别人的锁。
//   - 结束或失败时的释放只删除本进程本次创建的那个唯一文件名，绝不删除其他
//     请求的占用。
//   - 异常退出若发生在原子替换之前，本次业务变动完全不生效；发生在替换之后，
//     完整提交已保留（即使来不及输出成功），重试按已有结果去重。遗留临时文件
//     凭 pid 确认持有者已退出后由后续写入者清理，存活请求的临时文件一律不动。
//
// 等待有上限（默认 10 秒，可用环境变量 STOCKROOM_LOCK_WAIT_MS 按毫秒调整）：
// 只接受十进制非负安全整数，0 表示仅尝试立即取得；非法或超出安全整数范围的
// 配置在任何等待前报标准错误并以退出码 2 结束，绝不退化为无限等待。超时明确
// 报错并以退出码 1 结束。

const LOCK_PREFIX = `.${DATA_FILENAME}.lock.`;
const LEGACY_LOCK_FILENAME = `.${DATA_FILENAME}.lock`;
const TMP_PREFIX = `.${DATA_FILENAME}.`;
const LOCK_WAIT_DEFAULT_MS = 10_000;
const LOCK_POLL_MS = 50;

interface WriteLock {
  release(): void;
}

/** 解析并校验等待上限：仅接受非负安全整数；0 = 仅立即尝试；非法配置抛用法错误（退出 2）。 */
function lockWaitLimitMs(): number {
  const raw = process.env.STOCKROOM_LOCK_WAIT_MS;
  if (raw === undefined) return LOCK_WAIT_DEFAULT_MS;
  const s = raw.trim();
  if (!/^\d+$/.test(s))
    throw new UsageError(
      `环境变量 STOCKROOM_LOCK_WAIT_MS 必须是非负整数毫秒（0 表示仅尝试立即取得），实际为：${raw}`,
    );
  const n = Number(s);
  if (!Number.isSafeInteger(n))
    throw new UsageError(
      `环境变量 STOCKROOM_LOCK_WAIT_MS 超出安全整数范围，拒绝启动（不能转换为无限等待）：${raw}`,
    );
  return n;
}

function pidAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch (e) {
    return (e as NodeJS.ErrnoException).code === 'EPERM'; // 存在但无权发信号：视为存活
  }
}

function sleepSync(ms: number): void {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

/** 把（可能含符号链接的）数据目录归一为真实路径，使同一目录的不同写法共用一把锁。 */
function resolveDataDir(dataDir: string): string {
  try {
    return realpathSync.native(dataDir);
  } catch {
    // 目录尚不存在：先归一父目录（父目录本身可能是符号链接），再拼上待创建的末级
    const abs = resolve(dataDir);
    const slash = Math.max(abs.lastIndexOf('/'), 0);
    const parent = abs.slice(0, slash) || '/';
    const base = abs.slice(slash + 1);
    try {
      return join(realpathSync.native(parent), base);
    } catch {
      return abs;
    }
  }
}

/**
 * 列出当前锁文件名：包括新式 .stockroom.json.lock.<pid>.<nonce> 与升级前的
 * 旧式单文件 .stockroom.json.lock；其余临时文件、数据文件一律忽略。
 */
function listLockFiles(dir: string): string[] {
  let names: string[];
  try {
    names = readdirSync(dir);
  } catch {
    return [];
  }
  return names.filter((n) => n === LEGACY_LOCK_FILENAME || n.startsWith(LOCK_PREFIX));
}

/**
 * 判断一个锁文件是否属于已退出的写进程（可安全回收）。
 * 新式锁的 pid 取自文件名：持有者仍存活时，无论内容为空、写了一半还是已写
 * 完整，都一律视为占用中——文件年龄与内容完整度从不作为抢占依据。
 * 旧式单文件锁（升级前遗留）回退读取首行 pid；无法解析内容时不按年龄抢占，
 * 避免误伤“创建后尚未写完持有者信息”的存活进程。
 */
function lockIsStale(dir: string, name: string): boolean {
  if (name.startsWith(LOCK_PREFIX)) {
    const rest = name.slice(LOCK_PREFIX.length);
    const dot = rest.indexOf('.');
    const pidPart = dot < 0 ? rest : rest.slice(0, dot);
    if (!/^\d+$/.test(pidPart)) return false; // 文件名异常：保守起见不回收
    return !pidAlive(Number(pidPart));
  }
  try {
    const m = /^(\d+) /m.exec(readFileSync(join(dir, name), 'utf8'));
    if (m === null) return false;
    return !pidAlive(Number(m[1]));
  } catch {
    return false;
  }
}

/**
 * 清理异常退出写进程遗留的临时文件。临时文件名形如
 * .stockroom.json.<pid>[.<nonce>].tmp；只有 pid 已退出的才删除，
 * 其他存活写入的临时文件一律不动。
 */
function cleanStaleTmpFiles(dir: string): void {
  let names: string[];
  try {
    names = readdirSync(dir);
  } catch {
    return;
  }
  for (const name of names) {
    if (!name.startsWith(TMP_PREFIX) || !name.endsWith('.tmp')) continue;
    const body = name.slice(TMP_PREFIX.length, -'.tmp'.length);
    const pidPart = body.split('.')[0]; // 兼容旧式 <pid>.tmp 与新式 <pid>.<nonce>.tmp
    if (!/^\d+$/.test(pidPart)) continue;
    if (pidAlive(Number(pidPart))) continue;
    try {
      unlinkSync(join(dir, name));
    } catch {
      /* 清理失败不影响本次写入 */
    }
  }
}

/**
 * 把一个已确认的遗留锁（死 pid）回收并立刻原子创建本请求的新锁。
 * 回收只针对传入的具体文件名：改名源失败说明他人已先回收，直接放弃。
 * 回收物的改名目标带本进程 pid 与 nonce，多个回收者并发时也互不踩脚。
 */
function reclaimAndCreate(dir: string, staleName: string, myLockPath: string): boolean {
  const trash = `.stockroom.json.lock.reclaimed.${process.pid}.${Math.random().toString(36).slice(2)}`;
  try {
    renameSync(join(dir, staleName), join(dir, trash)); // 源不存在则失败：他人已处理
  } catch {
    return false;
  }
  try {
    unlinkSync(join(dir, trash));
  } catch {
    /* 删除回收物失败不影响取得锁 */
  }
  try {
    writeFileSync(myLockPath, '', { flag: 'wx' });
  } catch (e) {
    if ((e as NodeJS.ErrnoException).code === 'EEXIST') return false; // 极罕见竞争：下一轮重试
    throw new DataError(`无法获取数据目录写入机会（创建锁文件失败）：${(e as Error).message}`);
  }
  return true;
}

/**
 * 获取数据目录的写入机会（有限等待 + 异常退出自动恢复）。成功返回后调用方独占
 * 该目录的写权限，必须在 finally 中 release()；结束或失败都只释放本请求自己的锁。
 */
function acquireWriteLock(dataDirRaw: string): WriteLock {
  const limit = lockWaitLimitMs(); // 非法配置在此即抛用法错误（退出 2），不进入等待
  const dir = resolveDataDir(dataDirRaw);
  try {
    mkdirSync(dir, { recursive: true }); // 首次使用：先建目录再竞争锁，并发创建同样安全
  } catch (e) {
    throw new DataError(`无法创建数据目录 ${dataDirRaw}：${(e as Error).message}`);
  }
  const nonce = Math.random().toString(36).slice(2);
  const myLockName = `${LOCK_PREFIX}${process.pid}.${nonce}`;
  const myLockPath = join(dir, myLockName);
  const deadline = Date.now() + limit;

  const finalize = (): WriteLock => {
    cleanStaleTmpFiles(dir);
    // 持有者信息写入失败不影响已取得的占用（归属由文件名决定）；忽略其错误，
    // 空内容锁在本进程存活期间同样绝不被接管。
    try {
      writeFileSync(myLockPath, `${process.pid} ${new Date().toISOString()} ${nonce}\n`, { flag: 'r+' });
    } catch {
      /* 忽略：锁的有效性只取决于文件名与存活 pid */
    }
    let released = false;
    return {
      release(): void {
        if (released) return;
        released = true;
        try {
          unlinkSync(myLockPath); // 只删除本请求自己的唯一锁文件
        } catch {
          /* 已不存在（被回收或已自行清理）：忽略 */
        }
      },
    };
  };

  for (;;) {
    // 1) 尝试原子创建自己的锁；没有任何现存锁时立即成功。
    try {
      writeFileSync(myLockPath, '', { flag: 'wx' });
      return finalize();
    } catch (e) {
      if ((e as NodeJS.ErrnoException).code !== 'EEXIST') {
        throw new DataError(`无法获取数据目录写入机会（创建锁文件失败）：${(e as Error).message}`);
      }
    }

    // 2) 已存在锁：找出属于已退出进程的遗留锁。存活进程的锁一律等待；
    //    多个等待者可能同时观察到同一个遗留锁，但“回收 + 创建”串行决胜。
    const stale = listLockFiles(dir).find((name) => lockIsStale(dir, name));
    if (stale !== undefined) {
      if (reclaimAndCreate(dir, stale, myLockPath)) return finalize();
      continue; // 回收竞争失败：重新观察最新状态
    }

    // 3) 全部锁都属于存活进程（或无法判定）：在等待上限内轮询。
    if (limit === 0 || Date.now() >= deadline) {
      throw new DataError(
        `数据目录正忙：等待写入机会超过 ${limit} 毫秒仍未获得（另一进程正在写入 ${dataDirRaw}）；` +
          `本次请求未做任何改动，请稍后重试`,
      );
    }
    sleepSync(LOCK_POLL_MS);
  }
}

