      pidPart = name.slice(TMP_PREFIX.length, -'.tmp'.length).split('.')[0];
    } else if (lockNamePid(name) !== null) {
      const pid = lockNamePid(name)!;
      pidPart = String(pid);
      isIdentity = true;
    }
