/**
 * 获取数据目录的写入机会（有限等待 + 异常退出自动恢复）。成功返回后调用方独占
 * 该目录的写权限，必须在 finally 中 release()；结束或失败都只释放本请求自己的锁。
 */
function acquireWriteLock(dataDirRaw: string): WriteLock {
  const limit = lockWaitLimitMs(); // 非法配置在此即抛用法错误（退出 2），不进入等待
  const dir = resolveDataDir(dataDirRaw);
  try {
    mkdirSync(dir, { recursive: true }); // 首次使用：先建目录再竞争锁，并发创建同样安全
  } catch (e) {
    throw new DataError(`无法创建数据目录 ${dataDirRaw}：${(e as Error).message}`);
  }
  const nonce = Math.random().toString(36).slice(2);
  const myLockName = `${LOCK_PREFIX}${process.pid}.${nonce}`;
  const myLockPath = join(dir, myLockName);
  const deadline = Date.now() + limit;

  const finalize = (): WriteLock => {
    cleanStaleTmpFiles(dir);
    // 持有者信息写入失败不影响已取得的占用（归属由文件名决定）；忽略其错误，
    // 空内容锁在本进程存活期间同样绝不被接管。
    try {
      writeFileSync(myLockPath, `${process.pid} ${new Date().toISOString()} ${nonce}\n`, { flag: 'r+' });
    } catch {
      /* 忽略：锁的有效性只取决于文件名与存活 pid */
    }
    let released = false;
    return {
      release(): void {
        if (released) return;
        released = true;
        try {
          unlinkSync(myLockPath); // 只删除本请求自己的唯一锁文件
        } catch {
          /* 已不存在（被回收或已自行清理）：忽略 */
        }
      },
    };
  };

  for (;;) {
    // 1) 尝试原子创建自己的锁；没有任何现存锁时立即成功。
    try {
      writeFileSync(myLockPath, '', { flag: 'wx' });
      return finalize();
    } catch (e) {
      if ((e as NodeJS.ErrnoException).code !== 'EEXIST') {
        throw new DataError(`无法获取数据目录写入机会（创建锁文件失败）：${(e as Error).message}`);
      }
    }

    // 2) 已存在锁：找出属于已退出进程的遗留锁。存活进程的锁一律等待；
    //    多个等待者可能同时观察到同一个遗留锁，但“回收 + 创建”串行决胜。
    const stale = listLockFiles(dir).find((name) => lockIsStale(dir, name));
    if (stale !== undefined) {
      if (reclaimAndCreate(dir, stale, myLockPath)) return finalize();
      continue; // 回收竞争失败：重新观察最新状态
    }

    // 3) 全部锁都属于存活进程（或无法判定）：在等待上限内轮询。
    if (limit === 0 || Date.now() >= deadline) {
      throw new DataError(
        `数据目录正忙：等待写入机会超过 ${limit} 毫秒仍未获得（另一进程正在写入 ${dataDirRaw}）；` +
          `本次请求未做任何改动，请稍后重试`,
      );
    }
    sleepSync(LOCK_POLL_MS);
  }
}

