  const reclaimAsLeader = (myVote: string): boolean => {
    const trash = `${RECLAIM_PREFIX}${process.pid}.${Math.random().toString(36).slice(2)}`;
    try {
      renameSync(gatePath, join(dir, trash)); // 临界区内：只有领导者会走到这里
    } catch {
      return false; // 闸门刚好被释放/替换：释放选票后重新观察
    }
    try {
      linkSync(idPath, gatePath);
    } catch (e) {
      if ((e as NodeJS.ErrnoException).code !== 'EEXIST')
        throw new DataError(`无法获取数据目录写入机会（认领锁闸门失败）：${(e as Error).message}`);
      // 理论不可达（临界区内无人能建闸门），保守处理：回收物已移走，重新观察
      return false;
    }
    try {
      unlinkSync(join(dir, trash));
    } catch {
      /* 删除回收物失败不影响取锁；后续取得写入机会时按死 pid 规则清理 */
    }
    try {
      unlinkSync(join(dir, myVote)); // 释放领导权：继任闸门（自己的）已就位
    } catch {
      /* 遗票无害，后续 cleanStaleFiles 清理 */
    }
    return true;
  };

  let myVote: string | undefined; // 非 undefined 表示本进程正在参与回收选举

  for (;;) {
    // 1) 原子认领固定闸门：不存在时 link 成功即持有；存在时 EEXIST。
    //    参与选举期间不做普通 link（闸门的后继只能诞生在选举临界区内）。
    if (myVote === undefined) {
      try {
        linkSync(idPath, gatePath);
        return finish();
      } catch (e) {
        if ((e as NodeJS.ErrnoException).code !== 'EEXIST') {
          removeIdentity();
          throw new DataError(`无法获取数据目录写入机会（认领锁闸门失败）：${(e as Error).message}`);
        }
      }
    }

    // 2) 闸门被占且属已退出进程：参选并选举唯一回收领导者。
    if (gateIsStale(dir)) {
      if (myVote === undefined) myVote = castVote(dir);
      if (!electionWon(dir, myVote)) {
        // 非领导者：等待现任领导者完成回收（或其崩溃后由次小选票接任）
        if (limit === 0 || Date.now() >= deadline) {
          try { unlinkSync(join(dir, myVote)); } catch { /* 忽略 */ }
          removeIdentity();
          throw new DataError(
            `数据目录正忙：等待写入机会超过 ${limit} 毫秒仍未获得（另一进程正在写入 ${dataDirRaw}）；` +
              `本次请求未做任何改动，请稍后重试`,
          );
        }
        sleepSync(ELECTION_POLL_MS);
        continue;
      }
      // 本进程是领导者：在选举临界区内回收并认领。
      if (reclaimAsLeader(myVote)) return finish();
      // 临界区操作竞争失败：退选并重新观察
      try { unlinkSync(join(dir, myVote)); } catch { /* 忽略 */ }
      myVote = undefined;
      continue;
    }

    // 3) 闸门属于存活进程（或无法判定）：退选（若在选），在等待上限内轮询。
    if (myVote !== undefined) {
      try { unlinkSync(join(dir, myVote)); } catch { /* 忽略 */ }
      myVote = undefined;
    }
    if (limit === 0 || Date.now() >= deadline) {
      removeIdentity();
      throw new DataError(
        `数据目录正忙：等待写入机会超过 ${limit} 毫秒仍未获得（另一进程正在写入 ${dataDirRaw}）；` +
          `本次请求未做任何改动，请稍后重试`,
      );
    }
    sleepSync(LOCK_POLL_MS);
  }
}

