/** 读取锁身份文件名中的 pid（.stockroom.json.lock.<pid>.<nonce>）；无法解析返回 null。 */
function lockNamePid(name: string): number | null {
  if (!name.startsWith(LOCK_PREFIX)) return null;
  const rest = name.slice(LOCK_PREFIX.length);
  const dot = rest.indexOf('.');
  const part = dot < 0 ? rest : rest.slice(0, dot);
  return /^\d+$/.test(part) ? Number(part) : null;
}

/** 回收选举选票名 .stockroom.json.lock.vote.<pid>.<nonce> 中的 pid；非选票返回 null。 */
function voteNamePid(name: string): number | null {
  if (!name.startsWith(VOTE_PREFIX)) return null;
  const rest = name.slice(VOTE_PREFIX.length);
  const dot = rest.indexOf('.');
  const part = dot < 0 ? rest : rest.slice(0, dot);
  return /^\d+$/.test(part) ? Number(part) : null;
}

/** O_EXCL 创建本进程的回收选票，返回选票文件名；反复碰撞则换 nonce。 */
function castVote(dir: string): string {
  for (let tries = 0; tries < 3; tries++) {
    const name = `${VOTE_PREFIX}${process.pid}.${Math.random().toString(36).slice(2)}`;
    try {
      writeFileSync(join(dir, name), '', { flag: 'wx' });
      return name;
    } catch (e) {
      if ((e as NodeJS.ErrnoException).code !== 'EEXIST')
        throw new DataError(`无法获取数据目录写入机会（回收选举失败）：${(e as Error).message}`);
    }
  }
  throw new DataError('无法获取数据目录写入机会：回收选票反复创建冲突');
}

/** 当前回收选举是否已由本进程获胜：存活选票中本进程选票文件名最小。 */
function electionWon(dir: string, myVote: string): boolean {
  let names: string[];
  try {
    names = readdirSync(dir);
  } catch {
    return false;
  }
  const alive = names.filter((n) => {
    const p = voteNamePid(n);
    return p !== null && pidAlive(p);
  });
  if (!alive.includes(myVote)) return false; // 本进程选票缺失：极端情况，重新参选
  return alive.sort()[0] === myVote;
}

/** 列出各进程的锁身份文件名（不含固定闸门、不含回收物）。 */
function listLockIdentities(dir: string): string[] {
  let names: string[];
  try {
    names = readdirSync(dir);
  } catch {
    return [];
  }
  return names.filter((n) => lockNamePid(n) !== null);
}

