/** 读取“按 pid 命名的协调文件”中的 pid（身份文件、协调者文件、协调者回收物）；不匹配返回 null。 */
function pidFromNamedLockFile(name: string): number | null {
  let body: string | undefined;
  if (name === LOCK_COORD) {
    body = ''; // 协调者固定名，pid 在内容里
  } else if (name.startsWith(COORD_PREFIX)) {
    body = name.slice(COORD_PREFIX.length);
  } else if (name.startsWith(LOCK_PREFIX)) {
    body = name.slice(LOCK_PREFIX.length);
  }
  if (body === undefined) return null;
  const part = body.split('.')[0];
  return /^\d+$/.test(part) ? Number(part) : null;
}

/**
 * 尝试成为本目录唯一的“回收协调者”：用硬链接从按本进程命名的协调者源文件
 * 原子认领固定协调文件名。返回 true 表示当选；false 表示已有（存活）协调者。
 * 协调者在整个闸门持有期间保持唯一且稳定，杜绝多个回收者并发移走闸门。
 */
function tryBecomeCoordinator(dir: string, src: string): boolean {
  const coordPath = join(dir, LOCK_COORD);
  try {
    linkSync(src, coordPath);
    return true;
  } catch (e) {
    if ((e as NodeJS.ErrnoException).code !== 'EEXIST')
      throw new DataError(`无法获取数据目录写入机会（认领回收协调文件失败）：${(e as Error).message}`);
  }
  // 已有协调者：读其记录的 pid，死了则把死协调者回收（rename 到按本进程命名的
  // 唯一回收物，原子决胜）后重试一次；存活则本次不当选。
  let pid = -1;
  try {
    const m = /^(\d+)/.exec(readFileSync(coordPath, 'utf8'));
    if (m !== null) pid = Number(m[1]);
  } catch {
    return false;
  }
  if (pid > 0 && !pidAlive(pid)) {
    const trash = `${COORD_PREFIX}${process.pid}.${Math.random().toString(36).slice(2)}`;
    try {
      renameSync(coordPath, join(dir, trash)); // 与其他回收死协调者的进程原子决胜
      try { unlinkSync(join(dir, trash)); } catch { /* 忽略，后续按死 pid 清理 */ }
    } catch {
      return false; // 他人已处理
    }
    try {
      linkSync(src, coordPath);
      return true;
    } catch (e2) {
      if ((e2 as NodeJS.ErrnoException).code === 'EEXIST') return false;
      throw new DataError(`无法获取数据目录写入机会（认领回收协调文件失败）：${(e2 as Error).message}`);
    }
  }
  return false;
}

/** 列出各进程的锁身份文件名（仅 .stockroom.json.lock.<pid>.<nonce>，不含闸门/协调者）。 */
function listLockIdentities(dir: string): string[] {
  let names: string[];
  try {
    names = readdirSync(dir);
  } catch {
    return [];
  }
  return names.filter(
    (n) => n !== LOCK_GATE && n !== LOCK_COORD && !n.startsWith(COORD_PREFIX) && lockNamePid(n) !== null,
  );
}

