    if (myVote !== undefined) {
      withdrawVote(myVote);
      myVote = undefined;
    }
    if (limit === 0 || Date.now() >= deadline) {
      removeIdentity();
      throw busyError();
    }
    sleepSync(LOCK_POLL_MS);
  }
}

