    if (limit === 0 || Date.now() >= deadline) {
      if (amCoordinator) releaseCoord();
      removeIdentity();
      throw busyError();
    }
    sleepSync(amCoordinator ? LOCK_POLL_MS : COORD_POLL_MS);
  }
}

function gateExists(dir: string): boolean {
  try {
    statSync(join(dir, LOCK_GATE));
    return true;
  } catch {
    return false;
  }
}

